mapper.select:
select ta.id, ta.code, ta.transfer_direction as transferDirection, ta.approve_status as approveStatus, ta.invalid_status as invalidStatus, tad.id as detailId, tad.sku_id as skuId, tad.sku_no as skuNo, ta.bill_date as billDate, tad.qty, tad.unit, ta.in_warehouse_name as inWarehouseName, ta.out_warehouse_name as outWarehouseName, tad.remark, ta.apply_user_name as applyUserName, ta.approve_user_name as approveUserName, ta.create_user_name as createUserName, ta.create_time as createTime, mi.code AS machineCode from transfer_application ta inner join transfer_application_detail tad on ta.id = tad.main_id and tad.is_deleted = false LEFT JOIN machine_info mi ON ta.id = mi.source_id
${params.sqlMap.default} and ta.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ta.id desc,tad.id desc

select count(distinct ta.id) from transfer_application ta left join transfer_application_detail tad on ta.id = tad.main_id and tad.is_deleted = false
${params.sqlMap.default} and ta.is_deleted = false
${params.permissionSql}

select ta.id, ta.code, ta.transfer_direction as transferDirection, ta.approve_status as approveStatus, ta.invalid_status as invalidStatus, tad.sku_id as skuId, tad.sku_no as skuNo, ta.bill_date as billDate, tad.qty, tad.unit, ta.in_warehouse_name as inWarehouseName, ta.out_warehouse_name as outWarehouseName, tad.remark, ta.apply_user_name as applyUserName, ta.approve_user_name as approveUserName, ta.create_user_name as createUserName, ta.create_time as createTime from transfer_application ta left join transfer_application_detail tad on ta.id = tad.main_id and tad.is_deleted = false
${params.sqlMap.default} and ta.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ta.id desc,tad.id desc

select ta.code as sourceCode, ta.id as sourceId, tad.id as sourceDetailId, ta.transfer_direction as transferDirection, ta.approve_status as approveStatus, tad.sku_id as skuId, tad.sku_no as skuNo, tad.qty as qty, ta.bill_date as billDate, ta.out_warehouse_id as outWarehouseId, ta.out_warehouse_name as outWarehouseName, ta.in_warehouse_id as inWarehouseId, ta.in_warehouse_name as inWarehouseName, ta.in_org_id as inOrgId, ta.in_org_name as inOrgName from transfer_application_detail tad inner join transfer_application ta on ta.id = tad.main_id and tad.is_deleted = false
ta.is_deleted = false and tad.id in
#{item}
